class SelectionTrait extends Trait {
    constructor(k) {
        super('selected');
        this.k = k;
    }
    renderIndex(index, container) {
        super.renderIndex(index, container);
        if (this.k) {
            if (this.contains(index)) {
                container.setAttribute('aria-selected', 'true');
            }
            else {
                container.setAttribute('aria-selected', 'false');
            }
        }
    }
}
